import{_ as e,o as s,c as t,a0 as o}from"./chunks/framework.DCluYYrN.js";const h=JSON.parse('{"title":"Выход из циклической загрузки","description":"","frontmatter":{},"headers":[],"relativePath":"ru_RU/guide/rescue-from-bootloop.md","filePath":"ru_RU/guide/rescue-from-bootloop.md"}'),n={name:"ru_RU/guide/rescue-from-bootloop.md"};function l(i,a,p,d,r,c){return s(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="intruduction" tabindex="-1">Выход из циклической загрузки <a class="header-anchor" href="#intruduction" aria-label="Permalink to &quot;Выход из циклической загрузки {#intruduction}&quot;">​</a></h1><p>При прошивке устройства могут возникать ситуации, когда устройство становится &quot;окирпиченным&quot;. Теоретически, если использовать fastboot только для прошивки загрузочного раздела или установить неподходящие модули, из-за которых устройство не загружается, то это можно восстановить соответствующими операциями. В данном документе описаны некоторые экстренные методы восстановления работоспособности &quot;окирпиченного&quot; устройства.</p><h2 id="кирпич-путем-перепрошивки-загрузочного-раздела" tabindex="-1">Кирпич путем перепрошивки загрузочного раздела <a class="header-anchor" href="#кирпич-путем-перепрошивки-загрузочного-раздела" aria-label="Permalink to &quot;Кирпич путем перепрошивки загрузочного раздела&quot;">​</a></h2><p>В KernelSU при прошивке загрузочного раздела могут возникнуть следующие ситуации:</p><ol><li>Загрузочный образ прошивается в неправильном формате. Например, если формат загрузки телефона - <code>gz</code>, а вы прошили образ в формате <code>lz4</code>, то телефон не сможет загрузиться.</li><li>Для корректной загрузки телефона необходимо отключить проверку AVB (обычно для этого требуется стереть все данные на телефоне).</li><li>Ядро содержит ошибки или не подходит для прошивки телефона.</li></ol><p>Независимо от ситуации, восстановить работоспособность можно путем <strong>прошивки стокового загрузочного образа</strong>. Поэтому в начале руководства по установке мы настоятельно рекомендуем создать резервную копию стокового загрузочного образа перед прошивкой. Если у вас нет резервной копии, вы можете получить оригинальную заводскую загрузку от других пользователей с таким же устройством, как у вас, или из официальной прошивки.</p><h2 id="окирпичивание-из-за-модулеи" tabindex="-1">Окирпичивание из-за модулей <a class="header-anchor" href="#окирпичивание-из-за-модулеи" aria-label="Permalink to &quot;Окирпичивание из-за модулей&quot;">​</a></h2><p>Установка модулей может быть более распространенной причиной окирпичивания устройства, но мы должны серьезно предупредить вас: <strong>Не устанавливайте модули из неизвестных источников</strong>! Поскольку модули обладают правами root, они могут нанести непоправимый ущерб вашему устройству!</p><h3 id="нормальные-модули" tabindex="-1">Нормальные модули <a class="header-anchor" href="#нормальные-модули" aria-label="Permalink to &quot;Нормальные модули&quot;">​</a></h3><p>Если вы прошили модуль, безопасность которого доказана, но он приводит к невозможности загрузки устройства, то такая ситуация легко восстанавливается в KernelSU без каких-либо проблем. KernelSU имеет встроенный Безопасный режим для спасения устройства:</p><h4 id="volume-down" tabindex="-1">Спасение, с зажатой клавишей уменьшения громкости <a class="header-anchor" href="#volume-down" aria-label="Permalink to &quot;Спасение, с зажатой клавишей уменьшения громкости {#volume-down}&quot;">​</a></h4><p>Вы можете попытаться использовать <strong>Безопасный режим</strong> для спасения вашего устройства. После входа в безопасный режим все модули будут отключены.</p><p>Войти в безопасный режим можно двумя способами:</p><ol><li>Встроенный безопасный режим некоторых систем; некоторые системы имеют встроенный безопасный режим, доступ к которому осуществляется долгим нажатием кнопки уменьшения громкости, в то время как другие (например, MIUI/HyperOS) могут включить безопасный режим в Recovery. При входе в безопасный режим системы KernelSU также переходит в безопасный режим и автоматически отключает модули.</li><li>Встроенный безопасный режим KernelSU; метод работы заключается в том, что после первого экрана загрузки необходимо <strong>непрерывно нажать клавишу уменьшения громкости более трех раз</strong>. Обратите внимание, что именно нажать-отпустить, нажать-отпустить, нажать-отпустить, а не нажать и удерживать.</li></ol><p>После входа в безопасный режим все модули на странице модулей менеджера KernelSU Manager отключаются, но можно выполнить операцию &quot;деинсталляция&quot; для удаления модулей, которые могут вызывать проблемы.</p><p>Встроенный безопасный режим реализован в ядре, поэтому вероятность пропуска ключевых событий из-за перехвата исключена. Однако для ядер, отличных от ГКИ, может потребоваться ручная интеграция кода, и за рекомендациями можно обратиться к официальной документации.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>KernelSU регистрирует слушатель клавиши громкости во время инициализации модуля ядра (загружается, когда ядро выполняет процесс init в режиме LKM), и отменяет регистрацию на этапе <code>on_post_fs_data</code> (перед загрузочной анимацией). Вам необходимо уловить момент и быстро нажать клавишу уменьшения громкости три раза после первого экрана загрузки. Если устройство загружается быстро или операция не была выполнена своевременно, безопасный режим может не сработать.</p><p>Если модуль записывает неразумный код в initrc, из-за которого устройство не может загрузиться, этот код все равно будет выполняться даже в безопасном режиме.</p></div><h4 id="manual-rescue" tabindex="-1">Ручное восстановление <a class="header-anchor" href="#manual-rescue" aria-label="Permalink to &quot;Ручное восстановление {#manual-rescue}&quot;">​</a></h4><p>Если безопасный режим не решает проблему, вы можете попробовать ручное восстановление. Выберите следующие методы в зависимости от состояния устройства.</p><p><strong>Метод 1: Использование ksud для управления модулями через ADB</strong></p><p>Если устройство может получить root shell через ADB, вы можете использовать командную строку <code>ksud</code> напрямую для отключения или удаления проблемного модуля:</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>После монтирования разделов <code>metadata</code> и <code>data</code> вы можете запустить команду <code>/data/adb/ksud</code> в режиме Recovery для управления модулями.</p><p>Поскольку устройства GKI используют общий <code>init</code>, модуль ядра KernelSU по-прежнему будет загружен в режиме Recovery, и вы сможете нормально использовать большинство функций <code>ksud</code> (например, установку функций).</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>adb shell</span></span>
<span class="line"><span>su</span></span>
<span class="line"><span>ksud module list          # Вывести список всех модулей</span></span>
<span class="line"><span>ksud module disable &lt;id&gt;  # Отключить проблемный модуль</span></span>
<span class="line"><span>ksud module uninstall &lt;id&gt; # Или удалить напрямую</span></span>
<span class="line"><span>reboot</span></span></code></pre></div><p><strong>Метод 2: Ручная очистка через Recovery</strong></p><p>Если вы не можете войти в систему (даже ADB не подключается), вам понадобится стороннее Recovery (например, TWRP) на устройстве.</p><p>Загрузка модулей KernelSU зависит от файла инъекции init.rc на стороне ядра и процесса ksud в пространстве пользователя. После удаления этих файлов и перезагрузки KernelSU не будет загружать никаких модулей.</p><p><strong>Шаги операции:</strong></p><ol><li>Войдите в Recovery (например, TWRP).</li><li>Смонтируйте раздел data:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /data</span></span></code></pre></div>(Возможно, вам сначала потребуется расшифровать раздел data. Конкретная операция зависит от устройства и метода расшифровки.)</li><li>Удалите ksud, чтобы предотвратить загрузку модулей:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -f /data/adb/ksud</span></span></code></pre></div></li><li>(Необязательно) Смонтируйте раздел metadata и удалите файл инъекции init.rc, сгенерированный модулем:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /metadata</span></span>
<span class="line"><span>rm -f /metadata/ksu/modules.rc</span></span>
<span class="line"><span>rm -f /metadata/watchdog/ksu/modules.rc</span></span></code></pre></div></li><li>Перезагрузите устройство:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reboot</span></span></code></pre></div></li></ol><p>KernelSU пропустит загрузку всех модулей после перезагрузки. После входа в систему вы можете снова открыть менеджер KernelSU для решения проблем с модулями.</p><h3 id="форматирование-данных-или-другие-вредоносные-модули" tabindex="-1">Форматирование данных или другие вредоносные модули <a class="header-anchor" href="#форматирование-данных-или-другие-вредоносные-модули" aria-label="Permalink to &quot;Форматирование данных или другие вредоносные модули&quot;">​</a></h3><p>Если описанные выше способы не помогли спасти устройство, то высока вероятность того, что установленный модуль имеет вредоносные операции или повредил устройство иным способом. В этом случае есть только два варианта:</p><ol><li>Стереть данные и прошить официальную систему полностью.</li><li>Обратиться в сервисную службу.</li></ol>`,32)])])}const m=e(n,[["render",l]]);export{h as __pageData,m as default};
